type RiskAlertRow = {
	level: "low" | "medium" | "high" | "critical";
	title: string;
	description: string;
	score: number;
};

type UiApprover = {
	name: string;
	role: string;
	initials: string;
	status: "approved" | "pending" | "rejected";
	time: string | null;
};

type TimelineItem = {
	event: string;
	time: string;
	type: "success" | "warning" | "error" | "info";
};

